    // ===== ViewModel 基类：INotifyPropertyChanged 封装 =====
    public class ObservableObject : INotifyPropertyChanged
    {
        public event PropertyChangedEventHandler PropertyChanged;

        protected virtual void OnPropertyChanged([CallerMemberName] string propertyName = null)
        {
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
        }

        protected bool SetProperty<T>(ref T field, T value, [CallerMemberName] string propertyName = null)
        {
            if (EqualityComparer<T>.Default.Equals(field, value))
                return false;
            field = value;
            OnPropertyChanged(propertyName);
            return true;
        }
    }

    // ===== RelayCommand：命令封装 =====
    public class RelayCommand : ICommand
    {
        private readonly Action<object> _execute;
        private readonly Predicate<object> _canExecute;

        public RelayCommand(Action<object> execute, Predicate<object> canExecute = null)
        {
            _execute = execute ?? throw new ArgumentNullException(nameof(execute));
            _canExecute = canExecute;
        }

        // CommandManager.RequerySuggested 在 UI 状态变化时自动触发 CanExecute 重评估
        public event EventHandler CanExecuteChanged
        {
            add => CommandManager.RequerySuggested += value;
            remove => CommandManager.RequerySuggested -= value;
        }

        public bool CanExecute(object parameter) => _canExecute?.Invoke(parameter) ?? true;
        public void Execute(object parameter) => _execute(parameter);
    }

    // ===== Model =====
    public class User
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Email { get; set; }
    }

    // ===== ViewModel =====
    public class MainViewModel : ObservableObject
    {
        private string _userName;
        private string _email;
        private string _statusMessage;

        public MainViewModel()
        {
            Users = new ObservableCollection<User>();
            AddCommand = new RelayCommand(_ => AddUser(), _ => CanAddUser());
            ClearCommand = new RelayCommand(_ => ClearUsers());
        }

        public ObservableCollection<User> Users { get; }

        public string UserName
        {
            get => _userName;
            set => SetProperty(ref _userName, value); // 自动触发 PropertyChanged
        }

        public string Email
        {
            get => _email;
            set => SetProperty(ref _email, value);
        }

        public string StatusMessage
        {
            get => _statusMessage;
            set => SetProperty(ref _statusMessage, value);
        }

        public ICommand AddCommand { get; }
        public ICommand ClearCommand { get; }

        private bool CanAddUser() => !string.IsNullOrWhiteSpace(UserName) && !string.IsNullOrWhiteSpace(Email);

        private void AddUser()
        {
            Users.Add(new User { Id = Users.Count + 1, Name = UserName, Email = Email });
            StatusMessage = $"已添加 {UserName}，共 {Users.Count} 条";
            UserName = string.Empty;
            Email = string.Empty;
        }

        private void ClearUsers()
        {
            Users.Clear();
            StatusMessage = "已清空";
        }
    }

    // ===== 自定义依赖属性控件 =====
    // 展示 DependencyProperty 的注册、值优先级、变更回调
    public class ValidationTextBox : TextBox
    {
        // Register：注册依赖属性，必须 static readonly，名称约定 Property 后缀
        public static readonly DependencyProperty LabelProperty =
            DependencyProperty.Register(
                nameof(Label),           // 属性名
                typeof(string),          // 属性类型
                typeof(ValidationTextBox), // 宿主类型
                new FrameworkPropertyMetadata(
                    string.Empty,
                    FrameworkPropertyMetadataOptions.BindsTwoWayByDefault,
                    OnLabelChanged));     // 变更回调

        public static readonly DependencyProperty IsRequiredProperty =
            DependencyProperty.Register(
                nameof(IsRequired), typeof(bool), typeof(ValidationTextBox),
                new PropertyMetadata(false));

        // CLR 包装器：内部只调 GetValue/SetValue，不要加额外逻辑
        public string Label
        {
            get => (string)GetValue(LabelProperty);
            set => SetValue(LabelProperty, value);
        }

        public bool IsRequired
        {
            get => (bool)GetValue(IsRequiredProperty);
            set => SetValue(IsRequiredProperty, value);
        }

        // 静态回调：DependencyPropertyChangedEventArgs 包含 OldValue 和 NewValue
        private static void OnLabelChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
        {
            var control = (ValidationTextBox)d;
            // 可以在此更新内部状态或触发重新布局
        }
    }

    // ===== 路由事件示例：自定义长按事件 =====
    public class LongPressButton : Button
    {
        // 注册路由事件，Bubble 策略
        public static readonly RoutedEvent LongPressEvent =
            EventManager.RegisterRoutedEvent(
                "LongPress", RoutingStrategy.Bubble,
                typeof(RoutedEventHandler), typeof(LongPressButton));

        public event RoutedEventHandler LongPress
        {
            add => AddHandler(LongPressEvent, value);
            remove => RemoveHandler(LongPressEvent, value);
        }

        private DateTime _pressTime;

        // Preview 隧道事件先于冒泡事件执行
        protected override void OnMouseLeftButtonDown(MouseButtonEventArgs e)
        {
            base.OnMouseLeftButtonDown(e); // 先调 base 让 Preview 事件正常传播
            _pressTime = DateTime.Now;
        }

        protected override void OnMouseLeftButtonUp(MouseButtonEventArgs e)
        {
            base.OnMouseLeftButtonUp(e);
            if ((DateTime.Now - _pressTime).TotalMilliseconds > 500)
            {
                // RaiseEvent 发起路由事件，冒泡传播到父元素
                RaiseEvent(new RoutedEventArgs(LongPressEvent));
            }
        }
    }
}
